<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO perishables(product_id,qty,received_date,expiry_date)VALUES(?,?,?,?)")->execute([$_POST['product_id'],$_POST['qty'],$_POST['received_date'],$_POST['expiry_date']]);go('perishables.php');}
$products=$p->query("SELECT id,name FROM products ORDER BY name")->fetchAll();$rows=$p->query("SELECT pe.*,p.name FROM perishables pe JOIN products p ON p.id=pe.product_id ORDER BY expiry_date")->fetchAll();page_head('Perecíveis');?>
<div class="grid g2"><div class="card"><h2>Novo lote</h2><form method="post"><?=csrf_field()?><label>Produto</label><select name="product_id"><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><div class="grid g3"><div><label>Qtd.</label><input name="qty" type="number" step=".01"></div><div><label>Entrada</label><input name="received_date" type="date" value="<?=date('Y-m-d')?>"></div><div><label>Validade</label><input name="expiry_date" type="date"></div></div><button class="primary">Salvar lote</button></form></div><div class="card"><h2>Alertas</h2><p>Vencidos: <b><?=count(array_filter($rows,fn($x)=>$x['expiry_date']<date('Y-m-d')))?></b></p><p>Próximos 3 dias: <b><?=count(array_filter($rows,fn($x)=>$x['expiry_date']>=date('Y-m-d')&&$x['expiry_date']<=date('Y-m-d',strtotime('+3 days'))))?></b></p></div></div>
<div class="card"><div class="table"><table><tr><th>Produto</th><th>Qtd.</th><th>Validade</th><th>Status</th></tr><?php foreach($rows as $x):$st=$x['expiry_date']<date('Y-m-d')?'Vencido':($x['expiry_date']<=date('Y-m-d',strtotime('+3 days'))?'Próximo':'OK');?><tr><td><?=e($x['name'])?></td><td><?=$x['qty']?></td><td><?=e($x['expiry_date'])?></td><td><span class="badge <?=badge_class($st)?>"><?=$st?></span></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>